static Bounds B(GameObject g){var rs=g.GetComponentsInChildren<Renderer>();bool first=true;var b=new Bounds();foreach(var rr in rs){if(rr is ParticleSystemRenderer)continue;if(first){b=rr.bounds;first=false;}else b.Encapsulate(rr.bounds);}return b;}
static void Cylinder(Transform r,string name,Vector3 pos,float radius,float height,Material m,int sides=24){var v=new List<Vector3>();var uv=new List<Vector2>();var t=new List<int>();for(int j=0;j<2;j++)for(int i=0;i<=sides;i++){float a=i*2*Mathf.PI/sides;v.Add(new Vector3(Mathf.Sin(a)*radius,(j-.5f)*height,Mathf.Cos(a)*radius));uv.Add(new Vector2(i/(float)sides,j));}for(int i=0;i<sides;i++){int n=i;t.AddRange(new[]{n,n+1,n+sides+1,n+1,n+sides+2,n+sides+1});}int bottom=v.Count;v.Add(new Vector3(0,-height/2,0));uv.Add(Vector2.zero);int top=v.Count;v.Add(new Vector3(0,height/2,0));uv.Add(Vector2.one);for(int i=0;i<sides;i++){t.AddRange(new[]{bottom,i+1,i,top,sides+1+i,sides+2+i});}var mesh=new Mesh();mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(t,0);mesh.RecalculateNormals();temporary.Add(mesh);var g=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(r,false);g.transform.localPosition=pos;g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<Renderer>().sharedMaterial=m;pieces.Add(g);}
static void Roof(Transform r,Vector3 p,float width,float length,float rise,Material mat){var v=new[]{new Vector3(-width/2,0,-length/2),new Vector3(width/2,0,-length/2),new Vector3(0,rise,-length/2),new Vector3(-width/2,0,length/2),new Vector3(width/2,0,length/2),new Vector3(0,rise,length/2)};var mesh=new Mesh();mesh.vertices=v;mesh.triangles=new[]{0,2,1,3,4,5,0,3,5,0,5,2,2,5,4,2,4,1};mesh.uv=new[]{Vector2.zero,Vector2.right,Vector2.up,Vector2.zero,Vector2.right,Vector2.up};mesh.RecalculateNormals();temporary.Add(mesh);var g=new GameObject("PitchedRoof",typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(r,false);g.transform.localPosition=p;g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<Renderer>().sharedMaterial=mat;pieces.Add(g);}
static void Pipe(Transform r,Vector3 a,Vector3 b,float radius,Material mat){Cylinder(r,"ProcessPipe",(a+b)/2,radius,(b-a).magnitude,mat,12);pieces[pieces.Count-1].transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
static void Frame(Transform r,float x,float z,float h,float width,float depth){for(int a=-1;a<=1;a+=2)for(int b=-1;b<=1;b+=2)Box(r,"FrameLeg",new Vector3(x+a*width/2,h/2,z+b*depth/2),new Vector3(.45f,h,.45f),dark);for(int side=-1;side<=1;side+=2){Beam(r,"CrossBrace",new Vector3(x-width/2,1,z+side*depth/2),new Vector3(x+width/2,h,z+side*depth/2),.22f,dark);Box(r,"HeadGirder",new Vector3(x,h,z+side*depth/2),new Vector3(width,.65f,.55f),steel);}}
static void Finish(GameObject root,string name){var mesh=Bake(root.transform,mats);mesh.name=name;string p=Root+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(p);if(old){EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;mesh.UploadMeshData(false);}else AssetDatabase.CreateAsset(mesh,p);foreach(var g in pieces)UnityEngine.Object.DestroyImmediate(g);pieces.Clear();foreach(var m in temporary)UnityEngine.Object.DestroyImmediate(m);temporary.Clear();root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=mats;var col=root.AddComponent<BoxCollider>();col.center=mesh.bounds.center;col.size=mesh.bounds.size;PrefabUtility.SaveAsPrefabAsset(root,Root+"/"+name+".prefab");Debug.Log("DISTRICT_ASSET "+name+" triangles="+mesh.triangles.Length/3+" size="+mesh.bounds.size);UnityEngine.Object.DestroyImmediate(root);}
