var root=new GameObject("RollingMill");var r=root.transform;for(int bay=-1;bay<=1;bay++){float x=bay*20;Box(r,"LongProductionBay",new Vector3(x,7.5f,0),new Vector3(20,15,110),steel);Roof(r,new Vector3(x,15,0),20.8f,112,4,oxide);Box(r,"RoofMonitor",new Vector3(x,19.5f,0),new Vector3(4,1.8f,95),dark);Roof(r,new Vector3(x,20.4f,0),5,97,1,oxide);for(int i=0;i<10;i++){if(bay!=0)Box(r,"HighWindow",new Vector3(x+bay*10.07f,12,-49+i*11),new Vector3(.12f,1.7f,8),dark);if(bay!=0)Box(r,"ColumnSeam",new Vector3(x+bay*10.05f,7.5f,-49+i*11),new Vector3(.12f,14,.16f),dark);}}Box(r,"SideAnnex",new Vector3(36,4,-25),new Vector3(12,8,55),steel);Roof(r,new Vector3(36,8,-25),12.5f,56,2,oxide);for(int i=-1;i<=1;i++)Box(r,"LoadingDoor",new Vector3(i*20,4,-55.12f),new Vector3(8,8,.2f),yellow);Finish(root,"RollingMill");
