root=new GameObject("BlastFurnaceUnit");r=root.transform;Cylinder(r,"FurnaceLowerShell",new Vector3(0,15,0),13,30,steel);Cylinder(r,"FurnaceMiddleShell",new Vector3(0,40,0),9,20,steel);Cylinder(r,"FurnaceNeck",new Vector3(0,58,0),5,16,dark);Cylinder(r,"ChargingTop",new Vector3(0,68,0),7,4,yellow);for(int i=0;i<3;i++){Cylinder(r,"HotBlastStove",new Vector3(-29,21,-19+i*19),5.4f,42,steel);Cylinder(r,"StoveDome",new Vector3(-29,43,-19+i*19),4.5f,3,oxide);Pipe(r,new Vector3(-29,35,-19+i*19),new Vector3(-10,35,-19+i*19),1.6f,steel);}Frame(r,0,0,52,27,27);foreach(float h in new[]{13f,30f,47f}){Box(r,"ServiceDeck",new Vector3(0,h,0),new Vector3(30,.35f,30),dark);for(int side=-1;side<=1;side+=2)Beam(r,"SafetyRail",new Vector3(-15,h+1.2f,side*15),new Vector3(15,h+1.2f,side*15),.12f,yellow);}Box(r,"CastHouse",new Vector3(0,7,-32),new Vector3(55,14,26),steel);Roof(r,new Vector3(0,14,-32),57,28,4,oxide);Pipe(r,new Vector3(4,64,0),new Vector3(26,64,0),2,dark);Pipe(r,new Vector3(26,64,0),new Vector3(26,26,18),2,dark);Beam(r,"InclinedFeedConveyor",new Vector3(42,6,32),new Vector3(0,64,0),2.5f,steel);Frame(r,32,26,18,8,8);Finish(root,"BlastFurnaceUnit");
