static float Distance(Vector2 p,Vector2 a,Vector2 b){var d=b-a;return Vector2.Distance(p,a+d*Mathf.Clamp01(Vector2.Dot(p-a,d)/d.sqrMagnitude));}
static void Road(Vector2 a,Vector2 b){if(Vector2.Distance(a,b)<.1f)return;roads.Add(new Segment(a,b));}
static Vector2 V(float x,float z){return new Vector2(x,z);}
static void Curve(Vector2[] p){for(int i=0;i<p.Length-1;i++){var a=p[Mathf.Max(0,i-1)];var b=p[i];var c=p[i+1];var d=p[Mathf.Min(p.Length-1,i+2)];var last=b;for(int k=1;k<=10;k++){float t=k/10f;var q=.5f*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t);Road(last,q);last=q;}}}
static void PlanRoads(){roads.Clear();foreach(float x in new[]{-1550f,-1370f,-1190f,-1010f,-850f})Road(V(x,-450),V(x,1050));foreach(float z in new[]{-450f,-200f,50f,300f,550f,800f,1050f})Road(V(-1550,z),V(-850,z));Curve(new[]{V(-780,-450),V(-780,-240),V(-690,-150),V(-600,-60),V(-600,180),V(-740,320),V(-740,550),V(-650,640),V(-650,1040)});Curve(new[]{V(-600,-60),V(-480,-180),V(-420,-200),V(-330,-200)});Curve(new[]{V(-740,320),V(-630,430),V(-550,510)});Curve(new[]{V(-850,800),V(-750,800),V(-650,900)});Road(V(-850,-200),V(-775,-200));Road(V(-850,300),V(-740,300));Curve(new[]{V(-850,50),V(-720,50),V(-600,120)});Curve(new[]{V(-650,700),V(-520,830),V(-370,980)});}
static bool RoadHits(Segment s,Bounds b){float enter=0,exit=1;for(int axis=0;axis<2;axis++){float p=axis==0?s.a.x:s.a.y;float d=axis==0?s.b.x-s.a.x:s.b.y-s.a.y;float min=(axis==0?b.min.x:b.min.z)-13,max=(axis==0?b.max.x:b.max.z)+13;if(Mathf.Abs(d)<.001f){if(p<min||p>max)return false;}else{float a=(min-p)/d,c=(max-p)/d;if(a>c){float temp=a;a=c;c=temp;}enter=Mathf.Max(enter,a);exit=Mathf.Min(exit,c);if(enter>exit)return false;}}return true;}
static bool Free(Bounds b){b.Expand(new Vector3(10,0,10));if(b.max.x> -300||b.min.x< -1540||b.min.z< -435||b.max.z>1040)return false;foreach(var o in occupied){if(b.min.x<o.max.x&&b.max.x>o.min.x&&b.min.z<o.max.z&&b.max.z>o.min.z)return false;}foreach(var road in roads)if(RoadHits(road,b))return false;return true;}
static bool Place(string type,float x,float z,float yaw,float scale,string zone){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/"+type+".prefab");var g=(GameObject)PrefabUtility.InstantiatePrefab(asset);g.transform.SetParent(districtRoot,false);g.transform.localScale=Vector3.one*scale;g.transform.rotation=Quaternion.Euler(0,yaw,0);var b=B(g);g.transform.position+=new Vector3(x-b.center.x,-b.min.y,z-b.center.z);b=B(g);if(!Free(b)){UnityEngine.Object.DestroyImmediate(g);return false;}g.name=zone+"_"+type+"_"+buildingCount;occupied.Add(b);buildingCount++;log.AppendLine("|"+g.name+"|"+g.transform.position.ToString("F1")+"|"+yaw+"|"+scale.ToString("F2")+"|"+b.size.ToString("F1")+"|");return true;}
static void DrawRoads(){var root=new GameObject("DistrictRoads_24m_GridCurvesAnd45deg");root.transform.SetParent(districtRoot,false);foreach(var s in roads){float len=Vector2.Distance(s.a,s.b);var a=new Vector3(s.a.x,.009f,s.a.y);var b=new Vector3(s.b.x,.009f,s.b.y);Box(root.transform,"ServiceRoad",(a+b)/2,new Vector3(24,.012f,len+.25f),dark);pieces[pieces.Count-1].transform.localRotation=Quaternion.Euler(0,Mathf.Atan2(b.x-a.x,b.z-a.z)*Mathf.Rad2Deg,0);if(len>30)for(float f=8;f<len-5;f+=20){var p=Vector3.Lerp(a,b,f/len);Box(root.transform,"RoadCentreDash",p+Vector3.up*.012f,new Vector3(.18f,.008f,5),yellow);pieces[pieces.Count-1].transform.rotation=Quaternion.Euler(0,Mathf.Atan2(b.x-a.x,b.z-a.z)*Mathf.Rad2Deg,0);}}
var mesh=Bake(root.transform,mats);mesh.name="DistrictRoads";string path=District+"/DistrictRoads.asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;mesh.UploadMeshData(false);}else AssetDatabase.CreateAsset(mesh,path);foreach(var g in pieces)UnityEngine.Object.DestroyImmediate(g);pieces.Clear();root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=mats;}
