log=new System.Text.StringBuilder("# 왼쪽 공장 확장 결과\n\n## 창고 조정\n");void Move(string name,float dx,float dz,float yaw){var g=GameObject.Find(name);g.transform.position+=new Vector3(dx,0,dz);g.transform.rotation=Quaternion.Euler(0,yaw,0);log.AppendLine("- "+name+": 이동("+dx+", "+dz+"), Y회전 "+yaw+"도");}
