while(added<120&&attempts++<90000){int pick=random.Next(100);int type=pick<42?0:pick<69?1:pick<86?2:pick<98?3:4;float x,z;bool east=attempts%2==0;if(east){x=-820+(float)random.NextDouble()*495;z=-410+(float)random.NextDouble()*1410;}else{x=-1510+(float)random.NextDouble()*650;z=-410+(float)random.NextDouble()*1410;}float yaw=x< -850?(random.Next(2)*90):new[]{45f,-45f,20f,-20f,65f,0f}[random.Next(6)];float scale=.76f+(float)random.NextDouble()*.22f;float a=yaw*Mathf.Deg2Rad;var raw=bounds[type].size*scale;var size=new Vector3(Mathf.Abs(Mathf.Cos(a))*raw.x+Mathf.Abs(Mathf.Sin(a))*raw.z,raw.y,Mathf.Abs(Mathf.Sin(a))*raw.x+Mathf.Abs(Mathf.Cos(a))*raw.z);var proposed=new Bounds(new Vector3(x,size.y/2,z),size);if(!DenseFree(proposed))continue;var g=(GameObject)PrefabUtility.InstantiatePrefab(assets[type]);g.name="Infill_"+names[type]+"_"+added;g.transform.SetParent(group.transform,false);g.transform.localScale=Vector3.one*scale;g.transform.rotation=Quaternion.Euler(0,yaw,0);g.transform.position=proposed.center-g.transform.rotation*(bounds[type].center*scale);var actual=B(g);if(Vector3.Distance(actual.center,proposed.center)>.1f)throw new Exception("Bounds mismatch");occupied.Add(actual);added++;counts[type]++;if(x< -850)grid++;else irregular++;text.AppendLine("|"+g.name+"|"+g.transform.position.ToString("F1")+"|"+yaw+"|"+scale.ToString("F2")+"|"+actual.size.ToString("F1")+"|");}
