struct GroundStreet {public Vector2 a,b;public float width;public GroundStreet(Vector2 aa,Vector2 bb,float w){a=aa;b=bb;width=w;}}
static List<GroundStreet> streets=new List<GroundStreet>();
static bool StreetHits(GroundStreet s,Bounds b,float margin=0){float enter=0,exit=1;for(int axis=0;axis<2;axis++){float p=axis==0?s.a.x:s.a.y,d=axis==0?s.b.x-s.a.x:s.b.y-s.a.y;float min=(axis==0?b.min.x:b.min.z)-s.width/2-margin,max=(axis==0?b.max.x:b.max.z)+s.width/2+margin;if(Mathf.Abs(d)<.001f){if(p<min||p>max)return false;}else{float a=(min-p)/d,c=(max-p)/d;if(a>c){float temp=a;a=c;c=temp;}enter=Mathf.Max(enter,a);exit=Mathf.Min(exit,c);if(enter>exit)return false;}}return true;}
static Vector2 Closest(Vector2 p,GroundStreet s){var d=s.b-s.a;return s.a+d*Mathf.Clamp01(Vector2.Dot(p-s.a,d)/d.sqrMagnitude);}
static void FlatRoad(Transform parent,string name,Vector2 a,Vector2 b,float width,float y,Material mat){var tangent=(b-a).normalized;var side=new Vector2(-tangent.y,tangent.x)*width/2;var mesh=new Mesh();mesh.vertices=new[]{new Vector3(a.x+side.x,y,a.y+side.y),new Vector3(b.x+side.x,y,b.y+side.y),new Vector3(b.x-side.x,y,b.y-side.y),new Vector3(a.x-side.x,y,a.y-side.y)};mesh.triangles=new[]{0,1,2,0,2,3};mesh.uv=new[]{Vector2.zero,Vector2.up,Vector2.one,Vector2.right};mesh.RecalculateNormals();temporary.Add(mesh);var g=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(parent,false);g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<Renderer>().sharedMaterial=mat;pieces.Add(g);}
static Material RoadMat(string path,string name,Color c){var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=c;m.SetFloat("_Smoothness",.08f);m.enableInstancing=true;AssetDatabase.CreateAsset(m,path+"/"+name+".mat");return m;}
[MenuItem("Anseong/Art/Build Ground Road Network")]
public static void AddGroundRoads(){EditorSceneManager.OpenScene(Scene);if(GameObject.Find("GroundRoadNetwork"))throw new Exception("Road network already exists");const string path="Assets/_Anseong/Art/Environment/GroundRoads";Folder(path);var asphalt=RoadMat(path,"Asphalt",new Color(.115f,.13f,.135f));var white=RoadMat(path,"RoadWhite",new Color(.77f,.77f,.70f));var lineYellow=RoadMat(path,"CentreYellow",new Color(.76f,.56f,.13f));var shoulder=RoadMat(path,"Shoulder",new Color(.27f,.28f,.26f));var roadMats=new[]{asphalt,white,lineYellow,shoulder};
var roots=new List<GameObject>();foreach(var t in UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None)){if(!PrefabUtility.IsOutermostPrefabInstanceRoot(t.gameObject))continue;var assetPath=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject);if(assetPath.Contains("Art/Environment/Assets/"))roots.Add(t.gameObject);}var originals=new Dictionary<GameObject,Saved>();foreach(var g in roots)originals[g]=new Saved{t=g.transform,p=g.transform.position,q=g.transform.rotation,s=g.transform.localScale,name=g.name};
PlanRoads();streets.Clear();foreach(var r in roads)streets.Add(new GroundStreet(r.a,r.b,7.4f));streets.Add(new GroundStreet(V(-160,-280),V(-160,320),7.4f));streets.Add(new GroundStreet(V(160,-280),V(160,520),7.4f));streets.Add(new GroundStreet(V(-160,-280),V(160,-280),7.4f));streets.Add(new GroundStreet(V(-160,280),V(160,280),7.4f));streets.Add(new GroundStreet(V(-330,-200),V(-290,-240),7.4f));streets.Add(new GroundStreet(V(-290,-240),V(-160,-240),7.4f));
var report=new System.Text.StringBuilder("# 지상 도로망과 건물 정렬\n\n도로는 GroundRoadNetwork 독립 오브젝트이며 바닥 재질과 분리. 왕복2차로7.4m(방향당1차로), 시설 진입로 단차로4.2m. 지면 Y0 기준 표면 Y0.035~0.047m. 교통/운전 시스템은 없음.\n\n## 정렬된 건물\n");var buildings=new List<GameObject>();foreach(var g in roots){string a=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(g);if(a.Contains("Warehouse/")||a.Contains("UtilityPlant/")||a.EndsWith("RollingMill.prefab")||a.EndsWith("SteelmakingHall.prefab")||a.EndsWith("UtilityPumpStation.prefab"))buildings.Add(g);}int aligned=0,approaches=0;var eligible=new HashSet<GameObject>();
foreach(var g in buildings){var old=B(g);var centre=new Vector2(old.center.x,old.center.z);GroundStreet nearest=streets[0];Vector2 q=Closest(centre,nearest);float dist=Vector2.Distance(centre,q);foreach(var road in streets){var p=Closest(centre,road);float d=Vector2.Distance(centre,p);if(d<dist){dist=d;q=p;nearest=road;}}if(dist>120)continue;float tangent=Mathf.Atan2(nearest.b.x-nearest.a.x,nearest.b.y-nearest.a.y)*Mathf.Rad2Deg;float yaw=g.transform.eulerAngles.y,best=yaw,delta=360;for(int k=0;k<4;k++){float candidate=tangent+k*90;float d=Mathf.Abs(Mathf.DeltaAngle(yaw,candidate));if(d<delta){delta=d;best=candidate;}}var saved=originals[g];if(delta>.1f){g.transform.rotation=Quaternion.Euler(0,best,0);var b=B(g);g.transform.position+=old.center-b.center;b=B(g);bool clear=true;foreach(var other in roots){if(other==g)continue;var o=B(other);if(b.min.x<o.max.x+1&&b.max.x>o.min.x-1&&b.min.z<o.max.z+1&&b.max.z>o.min.z-1){clear=false;break;}}foreach(var road in streets)if(StreetHits(road,b,.6f)){clear=false;break;}if(clear){aligned++;report.AppendLine("- "+g.name+": Y回転 "+yaw.ToString("F1")+" → "+best.ToString("F1"));}else{g.transform.SetPositionAndRotation(saved.p,saved.q);continue;}}
eligible.Add(g);}
// Branches connect the nearest road to the building edge, perpendicular to its parallel facade.
