public static void AddLargeContainerYard(){EditorSceneManager.OpenScene(Scene);var previous=GameObject.Find("ContainerMarshallingYard");if(previous)Object.DestroyImmediate(previous);const string folder="Assets/_Anseong/Art/Environment/ContainerYard";Folder(folder);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Anseong/Art/Environment/Assets/ShippingContainer/ShippingContainer.prefab");var blockers=new List<Bounds>();foreach(var t in Object.FindObjectsByType<Transform>(FindObjectsSortMode.None))if(PrefabUtility.IsOutermostPrefabInstanceRoot(t.gameObject)&&PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject).Contains("Art/Environment/Assets/"))blockers.Add(B(t.gameObject));foreach(var n in new[]{"Player_ScaleOnly_65m","Opponent_ScaleOnly_65m"}){var b=B(GameObject.Find(n));b.Expand(new Vector3(45,0,45));blockers.Add(b);}var colors=new[]{new Color(.12f,.25f,.30f),new Color(.42f,.45f,.46f),new Color(.39f,.12f,.09f)};var mats=new Material[3];for(int i=0;i<3;i++){string path=folder+"/RandomPaint"+i+".mat";mats[i]=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mats[i])mats[i]=RoadMat(folder,"RandomPaint"+i,colors[i]);}var rng=new System.Random(428193);var root=new GameObject("ContainerMarshallingYard");var renderers=new List<MeshRenderer>();var centers=new[]{new Vector2(-95,-175),new Vector2(100,145),new Vector2(95,-185)};int[] widths={10,8,15},depths={7,5,10};int columns=0;var report=new System.Text.StringBuilder("# Three container clusters\n\nSeed 428193; System.Random.Next integer sampling (randint equivalent). Heights randomized 5–7 tiers. Three shared paints only: blue-grey, grey, red. Red assigned to exactly rounded 10% of shuffled container instances. Original mesh, dimensions, existing facilities and robot clearance preserved. No physics or damage states yet.\n\n");for(int k=0;k<3;k++){var block=new GameObject(k==2?"Cluster03_RightForeground_Largest":k==0?"Cluster01_Left_Medium":"Cluster02_RightRear_Small");block.transform.SetParent(root.transform);int subtotal=0;for(int row=0;row<depths[k];row++)for(int col=0;col<widths[k];col++){var c=centers[k]+new Vector2((col-(widths[k]-1)*.5f)*2.65f,(row-(depths[k]-1)*.5f)*6.4f);var footprint=new Bounds(new Vector3(c.x,9,c.y),new Vector3(2.5f,18,6.2f));bool clear=true;foreach(var b in blockers)if(footprint.Intersects(b)){clear=false;break;}if(!clear)continue;int levels=rng.Next(5,8);columns++;for(int level=0;level<levels;level++){var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab);g.name="Container_"+row+"_"+col+"_L"+(level+1)+"_Normal";g.transform.SetParent(block.transform);g.transform.rotation=Quaternion.Euler(0,rng.Next(0,2)*180,0);var bounds=B(g);g.transform.position+=new Vector3(c.x-bounds.center.x,level*2.59f-bounds.min.y,c.y-bounds.center.z);renderers.Add(g.GetComponent<MeshRenderer>());subtotal++;}}report.AppendLine(block.name+": "+subtotal+" containers; planned grid "+widths[k]+" x "+depths[k]);}for(int i=renderers.Count-1;i>0;i--){int j=rng.Next(0,i+1);var tmp=renderers[i];renderers[i]=renderers[j];renderers[j]=tmp;}int red=Mathf.RoundToInt(renderers.Count*.1f);for(int i=0;i<renderers.Count;i++){var slots=renderers[i].sharedMaterials;slots[0]=mats[i<red?2:rng.Next(0,2)];renderers[i].sharedMaterials=slots;}if(root.transform.childCount!=3)throw new Exception("Cluster count");report.AppendLine("Total="+renderers.Count+" columns="+columns+" red="+red+" ("+(100f*red/renderers.Count).ToString("F2")+"%). Right foreground planned footprint 150 columns versus previous 50 = 3x.");File.WriteAllText(folder+"/LayoutReport.md",report.ToString());AssetDatabase.Refresh();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);AssetDatabase.SaveAssets();Capture(Camera.main,"ContainerYard_ThreeClusters");Debug.Log("CONTAINER_THREE_PASS count="+renderers.Count+" red="+red+" clusters=3 randomHeight=5to7 sharedPaints=3");}
