File.WriteAllText(equipFolder+"/EquipmentList.md","# Container yard equipment\n\nImplemented static original models: 3 rail-mounted gantry cranes (32/26/46m span, approx29m height), trolley/hoist ropes/20ft spreader/cab/ladder/guardrails/travel bogies; ground rails; 3 terminal tractor + chassis units; 2 reach stackers for low-level transfer (not seven-tier stacking); control booth; 3 electrical cabinets; 8 concrete barriers; reused 3 streetlights. Single shared mesh per prefab and four shared materials. Model dimensions approximate visual design, not engineering specification. No operating animation/physics or VR performance validation.\n\nOptional future equipment: ship-to-shore crane if dedicated container berth is added, weighbridge, reefer socket racks only for refrigerated cargo, fire equipment/signage, maintenance shelter. Existing harbor cranes serve the steel berth separately.\n\nSources: https://rikoncranes.com/en/port-cranes/rtg-a-rtg/ (high stack handling); https://www.liebherr.com/en-au/maritime-cranes/products/port-equipment/rubber-tyre-gantry-cranes-4881362 (yard handling layout). This scene uses custom rail-mounted wide-span gantries, not an exact manufacturer RTG replica.\n");AssetDatabase.Refresh();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);AssetDatabase.SaveAssets();Capture(Camera.main,"ContainerYard_Equipment");Debug.Log("YARD_EQUIPMENT_PASS prefabs=10 gantries=3 tractors=3 reachStackers=2");}
[MenuItem("Anseong/Art/Apply Distant Mountain Sky")]
public static void ApplyDistantMountainSky(){EditorSceneManager.OpenScene(Scene);const string folder="Assets/_Anseong/Art/Environment/DistantBackdrop";AssetDatabase.Refresh();var shader=Shader.Find("Anseong/DistantMountainSky");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Backdrop shader invalid");var m=new Material(shader);m.name="CoastalDistantMountainSky";AssetDatabase.CreateAsset(m,folder+"/CoastalDistantMountainSky.mat");RenderSettings.skybox=m;RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogColor=new Color(.70f,.79f,.82f);RenderSettings.fogDensity=.000065f;foreach(var cam in Object.FindObjectsByType<Camera>(FindObjectsSortMode.None))cam.clearFlags=CameraClearFlags.Skybox;File.WriteAllText(folder+"/README.md","# Distant mountains and cloudy sky\n\nProcedural panoramic skybox: layered distant blue-grey ridgelines, atmospheric horizon and scattered white clouds. No mountain meshes, cloud geometry or source photograph pasted into the scene. Shared stereo-compatible sky shader; no runtime scripts. Fog is scene RenderSettings, not a ground material edit. Sea remains unbuilt. Skyline is decorative, cannot be approached. Current exposure/fog are first-pass; verify on headset.\n");AssetDatabase.Refresh();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);AssetDatabase.SaveAssets();Capture(Camera.main,"DistantBackdrop_Main");var go=new GameObject("BackdropPreviewCamera");var c=go.AddComponent<Camera>();c.CopyFrom(Camera.main);c.transform.position=new Vector3(0,65,-120);c.transform.rotation=Quaternion.Euler(-2,0,0);Capture(c,"DistantBackdrop_RobotHeight");Object.DestroyImmediate(go);Debug.Log("DISTANT_BACKDROP_PASS shaderErrors=0 skybox=true mountainGeometry=0 seaUnchanged=true");}
[MenuItem("Anseong/Art/Replace Sky Mountains With Terrain")]
public static void ReplaceSkyMountainsWithTerrain(){EditorSceneManager.OpenScene(Scene);const string folder="Assets/_Anseong/Art/Environment/DistantMountainTerrain";Folder(folder);var old=GameObject.Find("DistantMountainTerrain");if(old)Object.DestroyImmediate(old);var sky=new Material(Shader.Find("Skybox/Procedural"));sky.name="ClearAtmosphericSky";sky.SetColor("_SkyTint",new Color(.54f,.62f,.70f));sky.SetColor("_GroundColor",new Color(.59f,.68f,.72f));sky.SetFloat("_AtmosphereThickness",.9f);sky.SetFloat("_Exposure",1.05f);AssetDatabase.CreateAsset(sky,folder+"/ClearAtmosphericSky.mat");RenderSettings.skybox=sky;RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogColor=new Color(.65f,.74f,.79f);RenderSettings.fogDensity=.000023f;var root=new GameObject("DistantMountainTerrain");int total=0;for(int layer=0;layer<3;layer++){int nx=240,nz=40;float front=3200+layer*1900,depth=2400;var vertices=new Vector3[(nx+1)*(nz+1)];for(int iz=0;iz<=nz;iz++)for(int ix=0;ix<=nx;ix++){float x=-10000+20000f*ix/nx,z=front+depth*iz/nz;float u=(float)iz/nz;float envelope=Mathf.Pow(Mathf.Max(0,Mathf.Sin(u*Mathf.PI)),1.35f);float ridges=.35f+.65f*Mathf.PerlinNoise(x*.00039f+37+layer*11,layer*2.71f+4);float detail=Mathf.PerlinNoise(x*.0017f+12,z*.0014f+layer*31)*.75f+Mathf.PerlinNoise(x*.004f+7,z*.003f)*.25f;float mass=240+layer*100+650*ridges;float irregular=Mathf.PerlinNoise(x*.0008f+5,z*.0006f)*.5f+.65f;float y=-55+envelope*mass*irregular*(.65f+.35f*detail)*(.65f+layer*.4f);vertices[iz*(nx+1)+ix]=new Vector3(x,y,z);}var tris=new List<int>();for(int z=0;z<nz;z++)for(int x=0;x<nx;x++){int a=z*(nx+1)+x,b=a+1,ci=a+nx+1,d=ci+1;tris.AddRange(new[]{a,ci,b,b,ci,d});}var mesh=new Mesh{name="MountainRangeLayer"+layer};mesh.vertices=vertices;mesh.triangles=tris.ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();if(float.IsNaN(mesh.bounds.size.y))throw new Exception("Invalid mountain bounds");AssetDatabase.CreateAsset(mesh,folder+"/MountainLayer"+layer+".asset");var g=new GameObject("MountainRange_"+layer+"_"+(layer==0?"Foothills":layer==1?"Middle":"Distant"));g.transform.SetParent(root.transform);g.AddComponent<MeshFilter>().sharedMesh=mesh;var mat=RoadMat(folder,"AtmosphericRock"+layer,Color.Lerp(new Color(.43f,.52f,.55f),new Color(.64f,.72f,.77f),layer*.31f));mat.SetFloat("_Smoothness",0);mat.SetFloat("_Cull",0);g.AddComponent<MeshRenderer>().sharedMaterial=mat;total+=tris.Count/3;}foreach(var cam in Object.FindObjectsByType<Camera>(FindObjectsSortMode.None)){cam.farClipPlane=Mathf.Max(cam.farClipPlane,30000);cam.clearFlags=CameraClearFlags.Skybox;}File.WriteAllText(folder+"/README.md","# Distant mountain terrain\n\nReplaces the procedural mountain/cloud skybox with three actual terrain meshes behind the industrial area. Front edges approx3.2/5.1/7km away; 20km range width. Irregular eroded ridge and foothill profiles, per-layer atmospheric color and scene fog. 57600 triangles total, no colliders/physics. Clear procedural sky only; previous illustrated mountains/clouds are unassigned. Existing gameplay layout and sea opening preserved. Target camera far clip18km. VR headset validation pending.\n");AssetDatabase.Refresh();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);AssetDatabase.SaveAssets();Capture(Camera.main,"MountainTerrain_Main");var go=new GameObject("MountainPreviewCamera");var c=go.AddComponent<Camera>();c.CopyFrom(Camera.main);c.transform.position=new Vector3(0,65,-120);c.transform.rotation=Quaternion.Euler(-2,0,0);Capture(c,"MountainTerrain_RobotHeight");Object.DestroyImmediate(go);Debug.Log("MOUNTAIN_TERRAIN_PASS layers=3 triangles="+total+" illustratedSkyRemoved=true");}
[MenuItem("Anseong/Art/Lower Coastal Hills")]
public static void LowerCoastalHills(){EditorSceneManager.OpenScene(Scene);var root=GameObject.Find("DistantMountainTerrain");if(!root)throw new Exception("Missing mountain terrain");int layer=0;foreach(Transform t in root.transform){var mesh=t.GetComponent<MeshFilter>().sharedMesh;var v=mesh.vertices;int nx=240,nz=40;for(int iz=0;iz<=nz;iz++)for(int ix=0;ix<=nx;ix++){int n=iz*(nx+1)+ix;float x=v[n].x;float u=(float)iz/nz;float envelope=Mathf.Pow(Mathf.Max(0,Mathf.Sin(u*Mathf.PI)),1.1f);float profile=0;float[] centers={-9100,-7350,-3400,-2050,650,4900,6250,9200};float[] widths={1100,1450,1250,900,1600,1300,1050,1750};float[] heights={170,235,180,145,210,190,155,240};for(int k=0;k<centers.Length;k++){float shifted=centers[k]+(layer==0?0:layer==1?(k%2==0?430:-270):(k%3==0?-610:780));float triangle=Mathf.Max(0,1-Mathf.Abs(x-shifted)/widths[k]);float rounded=triangle*triangle*(3-2*triangle);profile=Mathf.Max(profile,rounded*heights[k]*(1+layer*.20f));}float detail=Mathf.PerlinNoise(x*.002f+9,u*3+layer*7);v[n].y=-45+envelope*profile*(.94f+.06f*detail);}mesh.vertices=v;mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);layer++;}AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);Capture(Camera.main,"RoundedIrregularHills_Main");var go=new GameObject("HillPreviewCamera");var c=go.AddComponent<Camera>();c.CopyFrom(Camera.main);c.transform.position=new Vector3(0,65,-120);c.transform.rotation=Quaternion.Euler(-2,0,0);Capture(c,"RoundedIrregularHills_RobotHeight");Object.DestroyImmediate(go);Debug.Log("LOW_COASTAL_HILLS_PASS layers="+layer+" peakLimits=300,430,600 roundedProfiles=true");}
[MenuItem("Anseong/Art/Connect Coastal Hinterland")]
public static void ConnectCoastalHinterland(){EditorSceneManager.OpenScene(Scene);const string folder="Assets/_Anseong/Art/Environment/DistantMountainTerrain";var previous=GameObject.Find("DistantMountainTerrain");if(previous)previous.SetActive(false);var prior=GameObject.Find("ConnectedCoastalHinterland");if(prior)Object.DestroyImmediate(prior);Material ground=null;foreach(var r in Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None)){var b=r.bounds;if(b.size.x>2500&&b.size.y<20&&Mathf.Abs(b.max.y)<2){ground=r.sharedMaterial;break;}}if(!ground)ground=RoadMat(folder,"HinterlandGround",new Color(.48f,.49f,.44f));int nx=240,nz=180;var vertices=new Vector3[(nx+1)*(nz+1)];for(int iz=0;iz<=nz;iz++)for(int ix=0;ix<=nx;ix++){float z=Mathf.Lerp(-3000,13000,(float)iz/nz);float bend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(3000,11000,z));float coastline=250+15500*bend;float x=Mathf.Lerp(-12000,coastline,(float)ix/nx);float y=0;float[] cx={-10400,-7600,-5950,-3100,-1650,-600,2700,6200,8400,12300};float[] cz={7800,8500,6200,8100,6400,9000,11200,11900,10800,12100};float[] wx={1800,1300,2100,1700,1300,1450,1700,2100,1300,2400};float[] wz={2700,2300,2600,3100,2100,2800,1700,1500,1600,1900};float[] heights={280,350,240,290,180,110,240,330,210,360};for(int k=0;k<cx.Length;k++){float dx=Mathf.Abs(x-cx[k])/wx[k],dz=Mathf.Abs(z-cz[k])/wz[k];float radius=Mathf.Sqrt(dx*dx+dz*dz);float q=Mathf.Clamp01(1-radius);float hill=q*q*(3-2*q);y=Mathf.Max(y,hill*heights[k]);}float landward=Mathf.Lerp(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(-2500,250,x)),1,Mathf.SmoothStep(0,1,Mathf.InverseLerp(9000,10500,z)));float flatStart=Mathf.SmoothStep(0,1,Mathf.InverseLerp(3200,4700,z));float detail=.95f+.05f*Mathf.PerlinNoise(x*.002f+17,z*.002f);y=y*landward*flatStart*detail;vertices[iz*(nx+1)+ix]=new Vector3(x,y-.08f,z);}var tris=new List<int>();for(int iz=0;iz<nz;iz++)for(int ix=0;ix<nx;ix++){int a=iz*(nx+1)+ix,b=a+1,ci=a+nx+1,d=ci+1;tris.AddRange(new[]{a,ci,b,b,ci,d});}var mesh=new Mesh{name="ConnectedCoastalHinterland"};mesh.vertices=vertices;mesh.triangles=tris.ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();if(float.IsNaN(mesh.bounds.size.y))throw new Exception("Invalid terrain");AssetDatabase.CreateAsset(mesh,folder+"/ConnectedCoastalHinterland.asset");var g=new GameObject("ConnectedCoastalHinterland");g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=ground;File.WriteAllText(folder+"/ConnectedHinterland.md","# Connected coastal hinterland\n\nContinuous non-colliding distant terrain mesh from Z-3000 to13000, extending inland to X-12000. Existing playable land top remains untouched; new plain sits0.08m below and continues past the old Z3000 edge. Footslopes rise smoothly only past3.2km, separate irregular broad hills further inland. Mountains taper to zero toward the right/coast (X250), leaving sea direction open. Existing coastline X250 preserved through play area; far coast bends gradually. Previous detached mountain layers disabled. 86400triangles; shared ground material; no sea geometry. VR validation pending.\n");AssetDatabase.Refresh();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);Capture(Camera.main,"ExtendedRightHinterland_Main");var go=new GameObject("HinterlandPreviewCamera");var c=go.AddComponent<Camera>();c.CopyFrom(Camera.main);c.transform.position=new Vector3(0,65,-120);c.transform.rotation=Quaternion.Euler(-2,0,0);Capture(c,"ExtendedRightHinterland_RobotHeight");Object.DestroyImmediate(go);Debug.Log("CONNECTED_HINTERLAND_PASS triangles="+tris.Count/3+" continuousPlain=true coastMountainsTaperToZero=true");}
