ransform);ocean.AddComponent<MeshFilter>().sharedMesh=mesh;ocean.AddComponent<MeshRenderer>().sharedMaterial=water;
int segments=520;var bv=new Vector3[(segments+1)*3];var bt=new List<int>();for(int z=0;z<=segments;z++){float zz=Mathf.Lerp(start,13000,(float)z/segments);float coast=250+15500*Mathf.SmoothStep(0,1,Mathf.InverseLerp(3000,11000,zz));float blend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(start,start+35,zz));bv[z*3]=new Vector3(coast-.12f,.01f,zz);bv[z*3+1]=new Vector3(coast+2*blend,-1.05f*blend,zz);bv[z*3+2]=new Vector3(coast+(2+Mathf.Lerp(5,40,Mathf.SmoothStep(0,1,Mathf.InverseLerp(start,start+600,zz))))*blend,-1.38f*blend,zz);if(z<segments)for(int x=0;x<2;x++){int a=z*3+x,c=a+3;bt.AddRange(new[]{a,c,a+1,a+1,c,c+1});}}var beachMesh=new Mesh{name="FiveMetreBeach"};beachMesh.vertices=bv;beachMesh.triangles=bt.ToArray();beachMesh.RecalculateNormals();beachMesh.RecalculateBounds();AssetDatabase.CreateAsset(beachMesh,folder+"/FiveMetreBeach.asset");var beach=new GameObject("FiveMetreSandBeach_AfterLastCrane");beach.transform.SetParent(root.transform);beach.AddComponent<MeshFilter>().sharedMesh=beachMesh;beach.AddComponent<MeshRenderer>().sharedMaterial=sand;File.WriteAllText(folder+"/README.md","# Ocean and narrow beach\n\nBeach begins15m after farthest harbor crane renderer bound: Z="+start.ToString("F1")+". 35m gradual transition; 2m bank plus sand width gradually increasing from5m to40m across600m follows current coast. Water level -1.35m. Ocean procedural shared shader: small waves, Fresnel sky color, sun glint and narrow shoreline foam. Opaque water, no realtime planar reflection/refraction or underwater system. Existing quay and assets unchanged. No collision/physics; headset performance unverified.\n");AssetDatabase.Refresh();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);Capture(Camera.main,"WideBeach_Main");var go=new GameObject("OceanPreviewCamera");var ccam=go.AddComponent<Camera>();ccam.CopyFrom(Camera.main);ccam.transform.position=new Vector3(0,65,-120);ccam.transform.rotation=Quaternion.Euler(-2,0,0);Capture(ccam,"WideBeach_RobotHeight");Object.DestroyImmediate(go);Debug.Log("OCEAN_BEACH_PASS beachStartZ="+start+" sandWidth=5to40 bankWidth=2 waterLevel=-1.35 shaderErrors=0");}
static Mesh SplitFactoryRoadMesh(Mesh src,bool factory){var dst=new Mesh{name=factory?"RotatingFactoryRoads":"FixedYardRoads",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};dst.vertices=src.vertices;dst.normals=src.normals;dst.uv=src.uv;dst.subMeshCount=src.subMeshCount;var verts=src.vertices;for(int sub=0;sub<src.subMeshCount;sub++){var triangles=src.GetTriangles(sub);var keep=new List<int>();for(int i=0;i<triangles.Length;i+=3){float x=(verts[triangles[i]].x+verts[triangles[i+1]].x+verts[triangles[i+2]].x)/3;if((x< -200)==factory)keep.AddRange(new[]{triangles[i],triangles[i+1],triangles[i+2]});}dst.SetTriangles(keep,sub);}dst.RecalculateBounds();return dst;}
