public static void RelocateFactoryBehindBoss(){EditorSceneManager.OpenScene(Scene);const string folder="Assets/_Anseong/Art/Environment/FactoryRearRelocation";Folder(folder);if(GameObject.Find("FactoryDistrict_Rear_Rotated90"))throw new Exception("Already relocated");var district=GameObject.Find("LeftFactoryDistrict");if(!district)throw new Exception("No factory district");var selected=new List<GameObject>{district};foreach(var t in Object.FindObjectsByType<Transform>(FindObjectsSortMode.None)){if(!PrefabUtility.IsOutermostPrefabInstanceRoot(t.gameObject)||t.IsChildOf(district.transform))continue;string path=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject);if(!path.Contains("Art/Environment/Assets/")||path.Contains("Quay/"))continue;if(B(t.gameObject).center.x< -200)selected.Add(t.gameObject);}var untouched=new Dictionary<Transform,Vector3>();foreach(var name in new[]{"Player_ScaleOnly_65m","Opponent_ScaleOnly_65m","ContainerMarshallingYard","ContainerYardOperations","CoastalOceanAndBeach"}){var g=GameObject.Find(name);if(g)untouched[g.transform]=g.transform.position;}float maxZ=float.MinValue;int prefabs=0;foreach(var g in selected){maxZ=Mathf.Max(maxZ,B(g).max.z);prefabs+=g.GetComponentsInChildren<MeshRenderer>().Length;}float shiftX=180-maxZ,shiftZ=350;var group=new GameObject("FactoryDistrict_Rear_Rotated90");foreach(var g in selected)g.transform.SetParent(group.transform,true);
