// Join the unchanged yard loop to an existing transformed internal road, without crossing buildings.
Vector3 endpoint=Vector3.zero;float score=float.PositiveInfinity;foreach(var vertex in factoryRoad.vertices){if(vertex.x>=-205)continue;var world=group.transform.TransformPoint(vertex);if(world.z<550||world.z>950)continue;float value=Mathf.Abs(world.x+160)+Mathf.Abs(world.z-600)*.3f;if(value<score){score=value;endpoint=world;}}if(float.IsInfinity(score))throw new Exception("No factory road connection");var roadRoot=new GameObject("FactoryAccessRoad_Reconnected");var mats=network.GetComponent<MeshRenderer>().sharedMaterials;var asphalt=AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/GroundRoadsV2/Asphalt.mat");var white=AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/GroundRoadsV2/RoadWhite.mat");var yellow=AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/GroundRoadsV2/CentreYellow.mat");var shoulder=AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/GroundRoadsV2/Shoulder.mat");var route=new Vector2[13];var pa=new Vector2(-160,280);var pb=new Vector2(-160,430);var pc=new Vector2(endpoint.x,endpoint.z-100);var pd=new Vector2(endpoint.x,endpoint.z);for(int j=0;j<route.Length;j++){float u=(float)j/(route.Length-1),v=1-u;route[j]=v*v*v*pa+3*v*v*u*pb+3*v*u*u*pc+u*u*u*pd;}pieces.Clear();for(int i=0;i<route.Length-1;i++){var a=route[i];var b=route[i+1];FlatRoad(roadRoot.transform,"FourLaneAsphalt",a,b,14.7f,.035f,asphalt);var d=(b-a).normalized;var n=new Vector2(-d.y,d.x);float length=Vector2.Distance(a,b);for(float f=10;f<length-8;f+=12){var q=a+d*f;FlatRoad(roadRoot.transform,"Centre",q,q+d*6,.13f,.047f,yellow);for(int side=-1;side<=1;side+=2){FlatRoad(roadRoot.transform,"Lane",q+n*3.5f*side,q+n*3.5f*side+d*6,.12f,.046f,white);}}}var connection=Bake(roadRoot.transform,new[]{asphalt,white,yellow,shoulder});AssetDatabase.CreateAsset(connection,folder+"/FactoryAccessRoad.asset");foreach(var g in pieces)Object.DestroyImmediate(g);pieces.Clear();foreach(var m in temporary)Object.DestroyImmediate(m);temporary.Clear();roadRoot.AddComponent<MeshFilter>().sharedMesh=connection;roadRoot.AddComponent<MeshRenderer>().sharedMaterials=new[]{asphalt,white,yellow,shoulder};foreach(var pair in untouched)if(Vector3.Distance(pair.Key.position,pair.Value)>.001f)throw new Exception("Fixed region moved");foreach(var name in new[]{"Player_ScaleOnly_65m","Opponent_ScaleOnly_65m"})if(Mathf.Abs(B(GameObject.Find(name)).size.y-65)>.2f)throw new Exception("Robot scale");File.WriteAllText(folder+"/RelocationReport.md","# Factory moved behind boss\n\nFactory district plus environmental prefab roots originally left ofX-200, excluding quay/cranes, moved together with90degree Y rotation (clockwise in top view). Translation="+group.transform.position+". Internal relative transforms/scales preserved via single parent transform. District eastern extent kept atX180, ahead of coastX250; nearest originalX-200 boundary nowZ550. Existing combined ground roads split atX-200 by triangle centroid; factory part rotates with district, yard part stays. Added four-lane connection from yard north-west corner into rotated road. Robots65m and container/harbor/beach/ocean transforms unchanged. Existing dense left site is now rear-left to rear, no duplicate buildings. VR/playtest not performed.\n\nSelected roots="+selected.Count+" renderers="+prefabs+" connector endpoint="+endpoint+"\n");AssetDatabase.Refresh();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);Capture(Camera.main,"RearFactory_Main");var go=new GameObject("RearFactoryPreviewCamera");var c=go.AddComponent<Camera>();c.CopyFrom(Camera.main);c.transform.position=new Vector3(0,65,-120);c.transform.rotation=Quaternion.Euler(-2,0,0);Capture(c,"RearFactory_RobotHeight");Object.DestroyImmediate(go);Debug.Log("REAR_FACTORY_PASS roots="+selected.Count+" rotation=90 preservedFixedRegions=true robots=65 roadReconnected=true");}
